"""Self-contained, offline visual inspection of a development study artifact.

The study builder owns aggregation and artifact verification. This renderer never
loads models, fits thresholds, or opens calibration/test data. All data strings
stay inert in a JSON script element and are inserted with textContent in the UI.
"""
from __future__ import annotations

import json
from pathlib import Path


def render_study_report(study: dict, output: Path) -> Path:
    """Render a nonempty study without changing or inventing its measurements."""
    if not isinstance(study, dict) or not isinstance(study.get("groups"), list) or not study["groups"]:
        raise ValueError("Study report requires nonempty groups from build_study")
    if any(not isinstance(group, dict) for group in study["groups"]):
        raise ValueError("Study groups must be objects")
    if study.get("schema_version") != 1 or study.get("phase") != "validation_development":
        raise ValueError("Study report accepts schema_version 1 validation_development artifacts only")
    payload = json.dumps(study, ensure_ascii=False, allow_nan=False)
    for char, escaped in (("&", r"\u0026"), ("<", r"\u003c"), (">", r"\u003e"),
                          ("\u2028", r"\u2028"), ("\u2029", r"\u2029")):
        payload = payload.replace(char, escaped)
    output = Path(output)
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(_HTML.replace("__STUDY_PAYLOAD__", payload), encoding="utf-8")
    return output


